class Solution {
public:
    vector<int> rearrangeArray(vector<int>& nums) {
        int n = nums.size();
        vector<int> res(n);
        int pos = 0, neg = 1;
        for (int x : nums) {
            if (x > 0) {
                res[pos] = x;
                pos += 2;
            } else {
                res[neg] = x;
                neg += 2;
            }
        }
        return res;
    }
};

class Solution {
    public int[] rearrangeArray(int[] nums) {
        int n = nums.length;
        int[] res = new int[n];
        int pos = 0, neg = 1;
        for (int x : nums) {
            if (x > 0) {
                res[pos] = x;
                pos += 2;
            } else {
                res[neg] = x;
                neg += 2;
            }
        }
        return res;
    }
}

var rearrangeArray = function(nums) {
    const res = new Int32Array(nums.length);
    let pos = 0, neg = 1;
    for (const x of nums) {
        if (x > 0) {
            res[pos] = x;
            pos += 2;
        } else {
            res[neg] = x;
            neg += 2;
        }
    }
    return Array.from(res);
};
